/// Memory / instruction files contributing to the system prompt
/// hierarchy — one list, shared by `memory_files` and
/// `system_prompt.memory_files`.
const KIMI_MEMORY_FILES: &[PathTemplate] = &[PathTemplate::Static("AGENTS.md")];

/// Builds the resource portability descriptor served through
/// `resource_support_fn` (heap-backed, so it lives behind the `LazyLock`
/// rather than in the `ProviderInfo` static).
fn build_resource_support() -> ProviderCapabilities {
    ProviderCapabilities {
        provider: Provider::KimiCode,
        skills: ResourceSupport {
            level: SupportLevel::Full,
            format: Some(ResourceFormat::Markdown),
            repo_path: Some(PathBuf::from(".kimi/skills")),
            user_path: Some(PathBuf::from(".config/agents/skills")),
            also_reads_from: vec![PathBuf::from(".claude/skills"), PathBuf::from(".agents/skills"), PathBuf::from(".codex/skills")],
            notes: None,
            properties: Some(ResourcePropertySchema::new(
                &[],
                &["name", "description", "license", "compatibility", "metadata", "type"],
                "claudine/docs/cross-referencing/kimi-code.md",
            )),
        },
        commands: ResourceSupport {
            level: SupportLevel::Limited,
            format: Some(ResourceFormat::BuiltinOnly),
            repo_path: None,
            user_path: None,
            also_reads_from: vec![],
            notes: Some("Built-in slash commands only"),
            properties: None,
        },
        agents: ResourceSupport {
            level: SupportLevel::CustomFormat,
            format: Some(ResourceFormat::Yaml),
            repo_path: Some(PathBuf::from(".kimi/agents")),
            user_path: Some(PathBuf::from(".kimi/agents")),
            also_reads_from: vec![],
            notes: Some("YAML agent files loaded via --agent-file flag"),
            properties: Some(ResourcePropertySchema::new(
                &["name", "system_prompt_path", "tools"],
                &["extend", "system_prompt_args", "exclude_tools", "subagents"],
                "claudine/docs/cross-referencing/kimi-code.md",
            )),
        },
        scripts: ResourceSupport {
            level: SupportLevel::None,
            format: None,
            repo_path: None,
            user_path: None,
            also_reads_from: vec![],
            notes: Some("Scripts stored within skill directories"),
            properties: None,
        },
        skill_frontmatter: SkillFrontmatter {
            name: true,
            description: true,
            license: true,
            compatibility: true,
            metadata: true,
            allowed_tools: false,
            user_invocable: false,
            disable_model_invocation: false,
        },
    }
}
